class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = now;

    // Başlangıç zamanı ve mevcut jeton sayısı
    this._startTime = now();
    this._tokens = capacity; // Kova dolu başlar
  }

  _getCurrentTime() {
    return this.now();
  }

  _refill() {
    const currentTime = this._getCurrentTime();
    let elapsedSeconds = (currentTime - this._startTime) / 1000;

    // Zaman geri gitmemeli, en büyük zaman referans alınmalı
    if (elapsedSeconds < 0) {
      elapsedSeconds = 0;
    } else {
      // Eğer geçmişte başlangıç zamanından daha fazla zaman geçtiyse,
      // dolum hesaplamasında o ana kadar görülen en büyük zaman kullanılır.
      // Bu durumda startTime'yi güncellemek yerine, eklenen jetonları sınırlayacağız.
    }

    const tokensToAdd = elapsedSeconds * this.refillPerSecond;

    // Kapasiteyi aşmamalıyız
    if (this._tokens + tokensToAdd > this.capacity) {
      this._tokens = this.capacity;
    } else {
      this._tokens += tokensToAdd;
    }

    // Zamanı güncelle (en büyük zaman referansı)
    this._startTime = currentTime;
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n < 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this._tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n < 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    // n jetondan fazlaysa veya dolum hızı 0 ise ve yeterli jeton yoksa Infinity döndür
    if (n > this.capacity || this.refillPerSecond === 0) {
      if (this._tokens < n) {
        return Infinity;
      }
    }

    const needed = n - this._tokens;

    // Gerekli jeton yoksa veya dolum hızı 0 ise
    if (needed <= 0 || this.refillPerSecond === 0) {
      return 0;
    }

    const secondsNeeded = needed / this.refillPerSecond;
    return Math.ceil(secondsNeeded * 1000);
  }
}

module.exports = { TokenBucket };

