const { TokenBucket } = require('./kova.js');

// Test 1: Temel kullanım
console.log('Test 1: Temel kullanım');
let bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log('available():', bucket.available()); // 10
console.log('tryTake(5):', bucket.tryTake(5)); // true
console.log('available():', bucket.available()); // 5

// Test 2: Yetersiz jeton
bucket = new TokenBucket({ capacity: 5, refillPerSecond: 1 });
console.log('tryTake(10) (yetersiz):', bucket.tryTake(10)); // false
console.log('available():', bucket.available()); // hala 5

// Test 3: msUntil
bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log('msUntil(15) (capacity > n):', bucket.msUntil(15)); // Infinity
console.log('msUntil(8):', bucket.msUntil(8)); // 4000ms (4 saniye * 1000)

// Test 4: Kesikli dolum (sahte saat ile)
console.log('\nTest 4: Kesikli dolum');
let fakeNow = 0;
const nowFunc = () => fakeNow++;
bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: nowFunc });
console.log('available():', bucket.available()); // 10

fakeNow += 3000; // 3 saniye geçti
console.log('after 3s available():', bucket.available()); // 16 -> 10 (kapasite sınırı)

// Test 5: RangeError testleri
console.log('\nTest 5: RangeError');
try { new TokenBucket({ capacity: -1, refillPerSecond: 1 }); } catch(e) { console.log('capacity < 0:', e.message); }
try { new TokenBucket({ capacity: 10, refillPerSecond: NaN }); } catch(e) { console.log('refillPerSecond NaN:', e.message); }
try { bucket.tryTake(-5); } catch(e) { console.log('n < 0:', e.message); }

// Test 6: Zaman geri gitme durumu
console.log('\nTest 6: Zaman geri gitme');
fakeNow = 1000;
bucket = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: () => fakeNow });
console.log('available():', bucket.available()); // 5

fakeNow = 500; // Zaman geri gitti
console.log('after time goes back available():', bucket.available()); // hala 5 (ekleme yapmaz)

// Test 7: msUntil edge cases
bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log('msUntil(5) when have 5:', bucket.msUntil(5)); // 0
console.log('msUntil(6):', bucket.msUntil(6)); // 500

// Test 8: refillPerSecond = 0
bucket = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
console.log('\nTest 8: refillPerSecond = 0');
console.log('msUntil(5):', bucket.msUntil(5)); // Infinity (yetersiz)
console.log('msUntil(3):', bucket.tryTake(3) ? 'taken' : 'not taken');

console.log('\nTüm testler tamamlandı!');
"

