bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: () => fakeNow });
fakeNow = 500;
console.log('t=500ms, tokens:', bucket.available()); // 10

fakeNow = 800; // 300ms geçti -> 0.3s * 2 = 0.6 jeton
console.log('t=800ms, tokens:', bucket.available()); // 10.6

// msUntil(11) -> 0.4 jeton daha lazım -> 0.2 saniye -> 200ms
let result = bucket.msUntil(11);
console.log('msUntil(11):', result, '(beklenen: ~200ms)');

// Test: Infinity durumları
bucket = new TokenBucket({ capacity: 5, refillPerSecond: 2 });
console.log('\\n=== Infinity testleri ===');
console.log('msUntil(6):', bucket.msUntil(6), '(capacity > n)'); // Infinity
console.log('msUntil(100):', bucket.msUntil(100)); // Infinity

bucket = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
console.log('refill=0, msUntil(5):', bucket.msUntil(5), '(yetersiz)'); // Infinity
console.log('refill=0, msUntil(3):', bucket.tryTake(3) ? 'taken' : 'not taken'); // taken (varsa)

// Test: Kesirli dolum ve yuvarlama
bucket = new TokenBucket({ capacity: 100, refillPerSecond: 1 });
fakeNow = 0;
console.log('\\n=== Kesirli dolum test ===');
console.log('t=0:', bucket.available()); // 100

fakeNow = 500; // 0.5s -> 0.5 jeton
console.log('t=500ms:', bucket.available()); // 100.5

// msUntil(101) -> 0.5 jeton daha lazım -> 500ms
let result = bucket.msUntil(101);
console.log('msUntil(101):', result, '(beklenen: 500)');

fakeNow += 250; // 750ms toplam -> 0.75s * 1 = 0.75 jeton
console.log('t=750ms:', bucket.available()); // 100.75
result = bucket.msUntil(101);
console.log('msUntil(101):', result, '(beklenen: ~250)');
"

